insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0002-0000-4000-8000-000000000033', 'en', null, 'Algorithms', 'A plain-language tour of how algorithms work and why some are far faster than others. You will meet searching, sorting, recursion, graph traversal, greedy methods, and dynamic programming, and learn to reason about cost in time and space. Topic selection follows the overview in Wikipedia, the free encyclopedia (CC BY-SA 4.0).', null, 'foundations', 38, true, 'technology', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0002-0000-4000-8000-000000000033', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"An algorithm is best described as...","options":["a programming language","a step-by-step procedure that solves a problem in finite time","a kind of computer chip","a random guess at an answer"],"answer":1,"explanation":"An algorithm is a finite, well-defined sequence of steps that turns an input into a desired output."},{"prompt":"Big-O notation mainly describes...","options":["how much a program costs in dollars","the color of the code","how the running time or space grows as the input gets larger","the number of files in a project"],"answer":2,"explanation":"Big-O captures the growth rate of cost as input size n increases, ignoring constant factors."},{"prompt":"Binary search can only be used when the data is...","options":["already sorted","stored in a file","made of text","very small"],"answer":0,"explanation":"Binary search repeatedly halves a sorted range, so the ordering is what makes it work."},{"prompt":"Which sorting method repeatedly selects the smallest remaining item and places it next?","options":["merge sort","selection sort","quicksort","binary search"],"answer":1,"explanation":"Selection sort scans for the minimum of the unsorted part and moves it into position each pass."},{"prompt":"A recursive function is one that...","options":["runs forever","never returns a value","calls itself on a smaller version of the problem","uses only loops"],"answer":2,"explanation":"Recursion solves a problem by calling itself on smaller inputs until it reaches a base case."},{"prompt":"Which data structure follows Last-In, First-Out order?","options":["queue","stack","array","hash table"],"answer":1,"explanation":"A stack returns the most recently added item first, like a pile of plates."},{"prompt":"Breadth-first search explores a graph level by level using which helper structure?","options":["a stack","a queue","a tree","a hash of weights"],"answer":1,"explanation":"BFS uses a queue so that nearer vertices are visited before farther ones."},{"prompt":"Dynamic programming speeds things up mainly by...","options":["guessing the answer","storing and reusing solutions to overlapping subproblems","deleting the input","sorting the data first"],"answer":1,"explanation":"Dynamic programming remembers subproblem results so it never recomputes the same thing."}]}'::jsonb, null, 10),
  (2, 'What an algorithm is, and measuring efficiency', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Define what an algorithm is, explain why two correct programs can differ enormously in speed, and measure a program''s cost in two separate currencies: time and space. Warm-up: suppose you want to find one name in a paper phone book. Give two different methods you could use, and say which one you expect to be faster when the book is thick. Keep that intuition handy, because the whole course is really about turning that gut feeling into something you can count and compare precisely instead of guessing."},{"heading":"The idea","text":"An algorithm is a finite sequence of clear, unambiguous steps that turns an input into a correct output and then stops. Being correct is not enough; we also care how much work it does. We measure that by counting basic operations (comparisons, additions, swaps) as a function of the input size n, rather than in seconds, because seconds depend on the hardware and the language. This is time complexity. Separately, space complexity counts the extra memory an algorithm needs beyond the input itself. We usually report the worst case, the most work any input of size n can force, because it gives a dependable guarantee. The best case and average case matter too, but the worst case is the promise you can rely on."},{"heading":"Worked examples","text":"Summing an array of n numbers does about n additions and keeps one running total, so its time grows linearly, written O(n), and its extra space is constant, O(1). Finding the largest value is the same shape: one pass, one stored candidate. Now count pairs. The loop ''for i in list: for j in list: compare a[i] with a[j]'' does roughly n times n comparisons, which is n^2 operations, written O(n^2). If n is 1000, the linear job does about 1000 steps while the nested one does about 1000000. Same computer, same correct result, but a thousandfold gap in work. That gap is exactly what efficiency analysis is built to expose before you ever run the code."},{"heading":"Your turn","text":"1) Is counting how many items are in a list O(1) or O(n) if you must walk the whole list? 2) A function allocates a brand-new copy of its n-element input. What is its space complexity? 3) Which case gives a dependable upper bound: best or worst? 4) Does printing every pair of items in a list take O(n) or O(n^2) time? 5) Why do we count operations instead of seconds? Answers: 1) O(n), one step per item. 2) O(n), the copy grows with the input. 3) The worst case. 4) O(n^2), there are about n*n pairs. 5) Seconds depend on the machine and language, while operation counts describe the algorithm itself."},{"heading":"Common mistakes & exit ticket","text":"Mistake: calling a program ''fast'' because it finished quickly once, on a tiny input; speed on small data hides how cost grows. Mistake: confusing time with space, for example assuming a loop that runs many times must also use a lot of memory, when it may use only a couple of variables. Mistake: forgetting that correctness comes first; a blazing-fast wrong answer is worthless. Exit: (a) What two resources do we measure for an algorithm? (b) Why report the worst case? Answers: time and space; the worst case gives a guarantee that holds for every input of that size, so it is the promise you can safely build on."}]}'::jsonb, 'We measure cost in operations as a function of input size n, not in seconds, because seconds depend on the machine while operation counts do not.', 12),
  (3, 'Big-O notation and common growth rates', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Read and write Big-O expressions, rank the common growth rates from cheapest to most expensive, and simplify a messy operation count into its dominant term. Warm-up: you have two algorithms, one that does 100*n steps and one that does n^2 steps. For very large n, which one eventually wins, and roughly where does the crossover happen? Make a guess now; by the end of this lesson you will be able to justify it in one sentence instead of hand-waving about which looks smaller at a glance."},{"heading":"The idea","text":"Big-O describes how cost grows as the input size n grows, keeping only the term that dominates for large n and dropping constant factors. So O(3n + 7) becomes O(n), and O(n^2 + n) becomes O(n^2). The common growth rates, from cheapest to most expensive, are: O(1) constant, O(log n) logarithmic, O(n) linear, O(n log n) linearithmic, O(n^2) quadratic, and O(2^n) exponential. Constant means the cost does not depend on n at all. Logarithmic means each step roughly halves the work left. Exponential means adding one item can double the work, which quickly becomes impossible to run. Learning this ladder lets you predict whether an idea will scale long before you type it out."},{"heading":"Worked examples","text":"Looking up array element a[k] by index is O(1): the position is computed directly. Binary search on sorted data is O(log n), because each comparison discards half the remaining range; 1,000,000 items need only about 20 comparisons. A single pass over a list is O(n). Good comparison sorts like merge sort are O(n log n). A nested double loop over the same list is O(n^2). Trying every subset of n items is O(2^n). To simplify a count, keep the biggest term: 5n^2 + 100n + 9 is O(n^2), since for large n the n^2 part dwarfs the rest. That is why 100*n eventually beats n^2 only until n passes 100, after which n^2 pulls ahead and never looks back."},{"heading":"Your turn","text":"1) Simplify O(7n + 4) to its Big-O. 2) Which is faster for large n, O(n log n) or O(n^2)? 3) What growth rate halves the problem each step? 4) Simplify O(n^2 + 3n + 50). 5) Which is the only rate here that does not grow at all with n? Answers: 1) O(n). 2) O(n log n) is faster; it grows much more slowly. 3) O(log n), logarithmic. 4) O(n^2), the quadratic term dominates. 5) O(1), constant time, which ignores n entirely."},{"heading":"Common mistakes & exit ticket","text":"Mistake: keeping constant factors, writing O(2n) when O(n) is meant; Big-O deliberately ignores them. Mistake: keeping lower-order terms, like O(n^2 + n) instead of O(n^2). Mistake: assuming a lower Big-O always wins even on tiny inputs; for small n a ''worse'' rate with small constants can be quicker, and Big-O only describes the trend for large n. Exit: (a) Rank O(n), O(log n), and O(n^2) from cheapest to most expensive. (b) Simplify O(4n + 10). Answers: O(log n), then O(n), then O(n^2); and O(n)."}]}'::jsonb, 'Big-O drops constant factors and lower-order terms: O(3n + 7) is written O(n), because for large inputs the leading term is what dominates the cost.', 13),
  (4, 'Searching: linear and binary search', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Perform and compare the two basic ways to find a value in a collection: linear search and binary search. You will know their time costs and, just as important, when each one is the right tool. Warm-up: a friend thinks of a number between 1 and 100 and only tells you ''higher'' or ''lower'' after each guess. What is your first guess if you want to find the number in as few tries as possible, and why 50 rather than 1?"},{"heading":"The idea","text":"Linear search walks through the collection one item at a time and checks each one until it finds the target or runs out. It works on any list, sorted or not, and takes O(n) time in the worst case, since the target may be last or absent. Binary search is far faster but demands a sorted list. It checks the middle element: if that is the target, done; if the target is smaller, it repeats on the left half; if larger, on the right half. Each comparison throws away half of what remains, so it finishes in O(log n) time. The number-guessing game is binary search in disguise: guessing 50 first halves the range every time."},{"heading":"Worked examples","text":"Linear search for 7 in [4, 2, 7, 9]: check 4 (no), 2 (no), 7 (yes) at index 2. In the worst case you touch all n items. Binary search for 23 in the sorted list [3, 9, 15, 23, 31, 42, 55]: low=0, high=6, mid=3 holds 23, found in one step. Search for 15: mid index 3 is 23, too big, so move high to 2; new mid index 1 is 9, too small, so move low to 2; mid index 2 is 15, found. Here is the shape in plain pseudocode: ''while low <= high: mid = (low + high) / 2; if a[mid] == target return mid; else if a[mid] < target: low = mid + 1; else: high = mid - 1''."},{"heading":"Your turn","text":"1) Which search needs a sorted list? 2) What is the worst-case time of linear search on n items? 3) Roughly how many comparisons does binary search need for 1,000,000 sorted items? 4) On an unsorted list, which search must you use? 5) In binary search, if a[mid] is smaller than the target, which half do you keep? Answers: 1) Binary search. 2) O(n). 3) About 20, since log base 2 of a million is near 20. 4) Linear search. 5) The right half, so you set low = mid + 1."},{"heading":"Common mistakes & exit ticket","text":"Mistake: running binary search on unsorted data, which returns wrong answers because the halving logic assumes order. Mistake: an off-by-one in the loop bounds, such as using low < high and skipping the last element, or never updating mid, which loops forever. Mistake: assuming binary search is always better; for a short list, or one you search only once, the cost of sorting first may not pay off. Exit: (a) What is the time cost of binary search? (b) What must be true of the data first? Answers: O(log n); the data must be sorted."}]}'::jsonb, 'Binary search needs sorted input; linear search does not. The price of binary search''s speed is paid once, by keeping the data in order.', 12),
  (5, 'Sorting algorithms and how they compare', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe five classic sorting methods, say how each one orders a list, and compare them by time cost so you can pick a sensible default. Warm-up: think about how you sort a hand of playing cards you are dealt one at a time. You probably slide each new card into its correct spot among the ones already arranged. Hold on to that image, because it is almost exactly one of the algorithms below, and naming it will make the whole family easier to remember."},{"heading":"The idea","text":"The simple quadratic sorts run in O(n^2) time. Bubble sort repeatedly walks the list swapping any two neighbors that are out of order, letting large values bubble to the end. Selection sort finds the smallest remaining item each pass and places it next. Insertion sort grows a sorted region on the left, inserting each new item into place, which is the card-sorting image. These are easy to understand but slow on big data. The fast divide-and-conquer sorts run in O(n log n). Merge sort splits the list in half, sorts each half, and merges the two sorted halves. Quicksort picks a pivot, partitions items into those below and above it, and recurses on each side. Both scale far better, which is why libraries rely on them."},{"heading":"Worked examples","text":"Insertion sort on [3, 1, 2]: take 1, insert before 3, giving [1, 3, 2]; take 2, insert between 1 and 3, giving [1, 2, 3]. Selection sort on the same list: smallest is 1, swap to front [1, 3, 2]; smallest of the rest is 2, swap [1, 2, 3]. Merge sort on [5, 2, 8, 1]: split into [5, 2] and [8, 1], sort each to [2, 5] and [1, 8], then merge by repeatedly taking the smaller front item: 1, 2, 5, 8. Comparison at a glance: bubble, insertion, and selection are O(n^2) worst case; merge sort is O(n log n) always; quicksort is O(n log n) on average but O(n^2) in its rare worst case, which good pivot choices avoid."},{"heading":"Your turn","text":"1) Which sort grows a sorted region by inserting each new item, like sorting cards? 2) What is the worst-case time of selection sort? 3) Which sort always runs in O(n log n)? 4) What is quicksort''s average time? 5) Name one O(n^2) sort and one O(n log n) sort. Answers: 1) Insertion sort. 2) O(n^2). 3) Merge sort. 4) O(n log n). 5) For example, bubble sort at O(n^2) and merge sort at O(n log n)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: reaching for bubble sort on large data; it is fine for teaching but far too slow in practice. Mistake: assuming quicksort is always O(n log n); a poor pivot on already-sorted data can degrade it to O(n^2). Mistake: forgetting that merge sort needs extra O(n) space for the merge step, while insertion sort sorts in place. Exit: (a) Give the average time cost shared by merge sort and quicksort. (b) Name the three simple sorts that run in O(n^2). Answers: O(n log n); bubble sort, selection sort, and insertion sort."}]}'::jsonb, 'O(n^2) sorts (bubble, insertion, selection) are simple but slow on large inputs; O(n log n) sorts (merge, quick) scale far better and are what real libraries use.', 14),
  (6, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"The worst-case time of linear search over n items is...","options":["O(1)","O(log n)","O(n)","O(n^2)"],"answer":2,"explanation":"The target may be last or missing, so you may touch all n items, giving O(n)."},{"prompt":"Binary search runs in which time on a sorted list?","options":["O(n)","O(log n)","O(n log n)","O(n^2)"],"answer":1,"explanation":"Each comparison discards half the remaining range, so the cost is O(log n)."},{"prompt":"Which of these growth rates is the most expensive for large n?","options":["O(log n)","O(n)","O(n^2)","O(2^n)"],"answer":3,"explanation":"Exponential O(2^n) grows faster than any polynomial rate and quickly becomes unrunnable."},{"prompt":"Merge sort''s time cost in the worst case is...","options":["O(n)","O(n log n)","O(n^2)","O(2^n)"],"answer":1,"explanation":"Merge sort always splits and merges in O(n log n), regardless of the input order."},{"prompt":"Bubble sort''s worst-case time is...","options":["O(n)","O(n log n)","O(n^2)","O(log n)"],"answer":2,"explanation":"Bubble sort compares and swaps neighbors across the list many times, giving O(n^2)."},{"prompt":"Which operation is O(1), constant time?","options":["accessing an array element by its index","scanning a list for a value","sorting a list","visiting every pair of items"],"answer":0,"explanation":"An index gives the position directly, so access does not depend on n."}]}'::jsonb, null, 8),
  (7, 'Recursion and divide-and-conquer', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Write and trace recursive functions, identify the two parts every recursion must have, and recognize the divide-and-conquer pattern behind merge sort and binary search. Warm-up: imagine standing in a long line, unable to see the front, and you want to know your position. You ask the person ahead ''what number are you?'' If they do not know, they ask the person ahead of them, and so on. What simple answer does the very first person give, and how does the count travel back to you?"},{"heading":"The idea","text":"Recursion solves a problem by having a function call itself on a smaller input. It needs two parts: a base case, a smallest input answered directly without more calls, and a recursive step that reduces the problem and calls itself, moving toward the base case. Without a base case it never stops. Divide-and-conquer is a powerful use of recursion: split the problem into smaller independent pieces, solve each piece recursively, then combine the results. Merge sort divides the list, sorts halves, and merges. Binary search divides the range and recurses on one half. The person-in-line warm-up is recursion: the first person answers 1 (the base case), and each person adds one as the count returns, step by step, back to you."},{"heading":"Worked examples","text":"Factorial in pseudocode: ''fact(n): if n <= 1 return 1; else return n * fact(n - 1)''. Tracing fact(3): it returns 3 * fact(2) = 3 * (2 * fact(1)) = 3 * (2 * 1) = 6. The base case n <= 1 stops the chain. Summing a list: ''sum(list): if list is empty return 0; else return first + sum(rest)''. For [4, 5]: 4 + (5 + (0)) = 9. Divide-and-conquer in merge sort: ''sort(list): if length <= 1 return list; mid = length / 2; left = sort(first half); right = sort(second half); return merge(left, right)''. The base case is a list of zero or one item, already sorted, and each call shrinks the work until it reaches that base."},{"heading":"Your turn","text":"1) What are the two required parts of any recursion? 2) What does fact(4) evaluate to? 3) In ''sum(list)'', what is the base case? 4) Name two algorithms that use divide-and-conquer. 5) What happens if a recursion has no base case? Answers: 1) A base case and a recursive step. 2) 24, since 4 * 3 * 2 * 1 = 24. 3) An empty list, which returns 0. 4) Merge sort and binary search (quicksort also qualifies). 5) It calls itself forever and eventually crashes or runs out of memory."},{"heading":"Common mistakes & exit ticket","text":"Mistake: forgetting the base case, so the function recurses endlessly. Mistake: a recursive step that does not actually shrink the input, for example calling fact(n) instead of fact(n - 1), which also never terminates. Mistake: assuming recursion is always clearer or faster than a loop; sometimes a simple loop is both plainer and lighter on memory, since each pending call uses stack space. Exit: (a) Name the part of a recursion that stops it. (b) What pattern splits a problem, solves the pieces, and combines them? Answers: the base case; divide-and-conquer."}]}'::jsonb, 'Every recursion needs a base case that stops it and a recursive step that moves strictly toward that base case; without both, it either loops forever or returns nothing useful.', 13),
  (8, 'Core data structures and graph traversal', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Name the core data structures algorithms rely on, say what each is good at, and traverse a graph two ways: breadth-first and depth-first. Warm-up: think about how you would explore a maze. One approach is to follow a single path as far as it goes, backing up only when you hit a dead end. Another is to fan out, checking everything one step away, then everything two steps away. Which approach finds the nearest exit first, and which might wander deep down a wrong corridor before returning?"},{"heading":"The idea","text":"An array stores items in a row with fast O(1) access by index. A linked list chains items with pointers, making inserts cheap but index access slow. A stack is Last-In, First-Out; a queue is First-In, First-Out. A hash table maps keys to values with average O(1) lookup, perfect for ''have I seen this?''. A tree is a branching hierarchy with one root. A graph is vertices joined by edges, modeling networks and relationships. Two ways to visit every vertex: breadth-first search (BFS) explores level by level using a queue, so it reaches nearer vertices first. Depth-first search (DFS) plunges down one path using a stack or recursion, backtracking at dead ends. BFS is the fan-out maze; DFS is the follow-one-path maze."},{"heading":"Worked examples","text":"Take a graph where A connects to B and C, B connects to D, and C connects to D. BFS from A uses a queue: visit A, enqueue B and C; visit B, enqueue D; visit C (D already queued); visit D. Order: A, B, C, D, which is level by level. DFS from A uses a stack or recursion: visit A, go to B, go to D, then backtrack and visit C. Order: A, B, D, C, which dives deep first. A hash table shines here: keep a ''visited'' set so you never process a vertex twice, checking membership in about O(1). Both traversals run in O(V + E) time, touching every vertex and every edge once, where V is vertices and E is edges."},{"heading":"Your turn","text":"1) Which structure gives O(1) access by index? 2) Which traversal uses a queue and visits nearest vertices first? 3) Which structure is First-In, First-Out? 4) What does a hash table give you in about O(1) on average? 5) What is the time cost of BFS or DFS on a graph with V vertices and E edges? Answers: 1) An array. 2) Breadth-first search. 3) A queue. 4) Lookup, insertion, and membership checks by key. 5) O(V + E)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: forgetting the visited set in graph traversal, so cycles make the search loop forever. Mistake: swapping the helper structures, using a stack for BFS or a queue for DFS, which changes the visiting order. Mistake: assuming index access on a linked list is fast; it is O(n), since you must follow the chain. Exit: (a) Which traversal uses a stack or recursion and goes deep first? (b) What structure powers BFS? Answers: depth-first search; a queue."}]}'::jsonb, 'Pick the data structure by the operations you need most: fast index access favors arrays, fast lookup by key favors hash tables, and relationships between things favor graphs.', 14),
  (9, 'Greedy algorithms, dynamic programming, and problem solving', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Tell greedy algorithms apart from dynamic programming, apply dynamic programming to a small example, and follow a dependable routine for approaching any new problem. Warm-up: suppose you must give change for 41 cents using coins of 25, 10, 5, and 1. If you always hand over the largest coin that still fits, what sequence of coins do you give, and how many coins is that? Notice how you decided each step without ever looking ahead or undoing a choice; that habit has a name you will learn below."},{"heading":"The idea","text":"A greedy algorithm builds a solution by always taking the best-looking choice right now and never going back. Making change with standard coins is greedy: take the biggest coin that fits, repeat. Greedy is fast and simple, but it is only correct for problems where local choices lead to a global best; for some coin systems it fails. Dynamic programming (DP) handles problems with overlapping subproblems by solving each small subproblem once and storing the result, then combining stored answers for bigger inputs. A good routine for any problem: understand it and restate it, work a tiny example by hand, look for a pattern or subproblem, choose a method, then check edge cases. Deciding between greedy and DP is part of that choice."},{"heading":"Worked examples","text":"Greedy change for 41 cents: take 25 (16 left), take 10 (6 left), take 5 (1 left), take 1 (0 left), four coins total. Dynamic programming on Fibonacci: the naive recursion fib(n) = fib(n-1) + fib(n-2) recomputes the same values exponentially, in O(2^n). Store results instead: ''memo = empty; fib(n): if n <= 1 return n; if n in memo return memo[n]; memo[n] = fib(n-1) + fib(n-2); return memo[n]''. Now each value is computed once, giving O(n) time. Tracing fib(5) with storage: fib(2)=1, fib(3)=2, fib(4)=3, fib(5)=5, and each is reused rather than recomputed. That single idea, remembering subproblem answers, is what turns an impossible exponential job into a quick linear one."},{"heading":"Your turn","text":"1) Which method always takes the best local choice and never reconsiders? 2) What is the naive recursive Fibonacci''s time cost? 3) What does storing subproblem results change that cost to? 4) Name the property a problem needs for dynamic programming to help. 5) Give the first step of the problem-solving routine. Answers: 1) A greedy algorithm. 2) O(2^n), exponential. 3) O(n), linear. 4) Overlapping subproblems (the same smaller problems recur). 5) Understand and restate the problem before coding."},{"heading":"Common mistakes & exit ticket","text":"Mistake: trusting greedy on a problem where it is not proven correct; it can return a worse answer than the true best. Mistake: writing a naive recursion for a problem riddled with overlapping subproblems, which explodes exponentially when storage would make it linear. Mistake: coding before understanding, which is why the routine puts restating the problem and trying a tiny example first. Exit: (a) What does dynamic programming store and reuse? (b) When is greedy safe to use? Answers: solutions to overlapping subproblems; only when local best choices are proven to lead to the global best."}]}'::jsonb, 'Greedy makes the best local choice and never reconsiders; dynamic programming builds the answer from stored subproblem results. Greedy is simpler but only correct for certain problems.', 14),
  (10, 'Key terms', 'vocab', '{"items":[{"term":"algorithm","translation":"a finite, well-defined sequence of steps that turns an input into a correct output and then stops","example":"A recipe is an everyday algorithm: do these steps in order and you get the dish."},{"term":"time complexity","translation":"how the number of operations grows as the input size n grows","example":"Linear search has time complexity O(n)."},{"term":"space complexity","translation":"how much extra memory an algorithm needs beyond its input","example":"Summing a list in a single running total has O(1) space complexity."},{"term":"Big-O notation","translation":"a way to write growth rate while ignoring constant factors and lower-order terms","example":"O(3n + 5) is written simply as O(n)."},{"term":"binary search","translation":"finding a value in sorted data by repeatedly halving the search range","example":"Binary search locates an item among a million sorted entries in about 20 steps."},{"term":"recursion","translation":"a function that solves a problem by calling itself on a smaller input until a base case","example":"Computing a factorial with fact(n) = n * fact(n - 1) is recursion."},{"term":"greedy algorithm","translation":"a method that always takes the best local choice and never reconsiders it","example":"Making change by always handing over the largest fitting coin is greedy."},{"term":"dynamic programming","translation":"solving overlapping subproblems once and storing the results to reuse them","example":"Storing Fibonacci values turns an O(2^n) recursion into an O(n) one."}]}'::jsonb, null, 10)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0002-0000-4000-8000-000000000033' and l.position = v.pos
);
